code='''from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    lines = []
    for r in range(h):
        if len(set(grid[r])) == 1:
            lines.append((counts[grid[r][0]], "h", r))
    for c in range(w):
        if len({grid[r][c] for r in range(h)}) == 1:
            lines.append((counts[grid[0][c]], "v", c))
    _, axis, sep = min(lines)
    if axis == "h":
        a, b = grid[:sep], grid[sep+1:]
    else:
        a = [row[:sep] for row in grid]
        b = [row[sep+1:] for row in grid]
    ca, cb = set(x for row in a for x in row), set(x for row in b for x in row)
    shared = next(iter(ca & cb))
    out = [[shared] * len(a[0]) for _ in range(len(a))]
    for r in range(len(a)):
        for c in range(len(a[0])):
            if a[r][c] == b[r][c]:
                out[r][c] = 3
    return out
'''
